public class SafeParserTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("valid number", 42, SafeParser.parseOrDefault("42", 0));
        check("negative number", -7, SafeParser.parseOrDefault("-7", 0));
        check("letters fall back", 99, SafeParser.parseOrDefault("abc", 99));
        check("empty string falls back", 5, SafeParser.parseOrDefault("", 5));
        check("null falls back", 3, SafeParser.parseOrDefault(null, 3));
        check("decimal text falls back", 1, SafeParser.parseOrDefault("12.5", 1));
        check("text with spaces falls back", 8, SafeParser.parseOrDefault(" 4 ", 8));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

